// Test-only copy: lays the cottage floor (y1) and walls the shell will supply, to check the bath against its real floor.
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const [src, dst] = process.argv.slice(2);
const g = load(src);
g.fill([84, 1, 71], [86, 1, 74], "smooth_quartz");
g.fill([83, 2, 70], [87, 5, 70], "white_concrete");
g.fill([83, 2, 75], [87, 5, 75], "white_concrete");
g.fill([83, 2, 71], [83, 5, 74], "white_concrete");
g.fill([87, 2, 71], [87, 5, 74], "white_concrete");
g.fill([83, 6, 70], [87, 6, 75], "smooth_quartz");
g.set(85, 2, 70, "air");
g.set(85, 3, 70, "air");
g.save(dst);
EOF
node /tmp/bath-test-35/mkfloor.mjs build.nbt /tmp/bath-test-35/test.nbt && MCD="/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs"; node $MCD room /tmp/bath-test-35/test.nbt --rooms rooms.json --only "cottage bath" 2>&1 | tail -30; node $MCD fit /tmp/bath-test-35/test.nbt --rooms rooms.json 2>&1 | grep -i "cottage bath\|84,\|85,\|86," | head; date

